-- ===========================================================================
-- PIXME — initial schema
--
-- Conventions
--   * ids                : UUID, generated by the application
--   * timestamps         : timestamptz, always stored in UTC
--   * post_date          : plain DATE, the calendar day a PIXME belongs to,
--                          resolved in the service timezone (Asia/Seoul)
--   * enums              : varchar + CHECK, mapped as @Enumerated(STRING).
--                          Cheaper to evolve than a Postgres enum type.
--   * soft delete        : deleted_at on user-owned rows we must be able to
--                          withdraw from public surfaces instantly, before the
--                          hard purge runs.
-- ===========================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ------------------------------------------------------------------- users --

CREATE TABLE users (
    id                  UUID PRIMARY KEY,
    provider            VARCHAR(16)  NOT NULL,
    provider_user_id    VARCHAR(191) NOT NULL,
    email               VARCHAR(255),
    status              VARCHAR(24)  NOT NULL DEFAULT 'PENDING_PROFILE',
    -- Rolling signal used by the square's "지금 활동 중" rail and by ranking.
    last_active_at      TIMESTAMPTZ,
    suspended_until     TIMESTAMPTZ,
    suspension_reason   VARCHAR(255),
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- Set the moment the user asks for deletion; the purge job removes the row.
    deleted_at          TIMESTAMPTZ,
    CONSTRAINT users_provider_check
        CHECK (provider IN ('APPLE', 'KAKAO')),
    CONSTRAINT users_status_check
        CHECK (status IN ('PENDING_PROFILE', 'ACTIVE', 'SUSPENDED', 'DELETED'))
);

-- One account per (provider, provider id). Deleted accounts keep the row until
-- purge, so this stays unique across the whole table.
CREATE UNIQUE INDEX users_provider_identity_key
    ON users (provider, provider_user_id);
CREATE INDEX users_status_created_idx ON users (status, created_at DESC);
CREATE INDEX users_deleted_at_idx ON users (deleted_at) WHERE deleted_at IS NOT NULL;

CREATE TABLE user_profiles (
    user_id                UUID PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    nickname               VARCHAR(12),
    birth_date             DATE,
    gender                 VARCHAR(16),
    bio                    VARCHAR(60),
    -- Denormalised pointer to the character shown as this user's avatar.
    representative_post_id UUID,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_profiles_gender_check
        CHECK (gender IS NULL OR gender IN ('FEMALE', 'MALE', 'OTHER', 'UNDISCLOSED'))
);

-- Nicknames are unique case-insensitively so "MING" and "ming" can't coexist.
CREATE UNIQUE INDEX user_profiles_nickname_key
    ON user_profiles (lower(nickname)) WHERE nickname IS NOT NULL;

CREATE TABLE user_settings (
    user_id                  UUID PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    push_heart               BOOLEAN NOT NULL DEFAULT TRUE,
    push_connection_request  BOOLEAN NOT NULL DEFAULT TRUE,
    push_connected           BOOLEAN NOT NULL DEFAULT TRUE,
    push_message             BOOLEAN NOT NULL DEFAULT TRUE,
    push_daily_reminder      BOOLEAN NOT NULL DEFAULT TRUE,
    -- FALSE => the original photo is deleted as soon as generation finishes.
    keep_original_photo      BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at               TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Counters are denormalised because every feed card shows them; they are
-- maintained in the same transaction as the event that changes them.
CREATE TABLE user_stats (
    user_id              UUID PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    received_heart_count INTEGER NOT NULL DEFAULT 0,
    connection_count     INTEGER NOT NULL DEFAULT 0,
    pixel_count          INTEGER NOT NULL DEFAULT 0,
    streak_days          INTEGER NOT NULL DEFAULT 0,
    last_post_date       DATE,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_stats_non_negative
        CHECK (received_heart_count >= 0 AND connection_count >= 0 AND pixel_count >= 0)
);

-- --------------------------------------------------------------- interests --

CREATE TABLE interests (
    code       VARCHAR(32) PRIMARY KEY,
    label      VARCHAR(32) NOT NULL,
    emoji      VARCHAR(8)  NOT NULL,
    sort_order INTEGER     NOT NULL DEFAULT 0,
    active     BOOLEAN     NOT NULL DEFAULT TRUE
);

CREATE TABLE user_interests (
    user_id       UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    interest_code VARCHAR(32) NOT NULL REFERENCES interests (code),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, interest_code)
);

-- Reverse lookup drives "people who share your interests" in feed ranking.
CREATE INDEX user_interests_interest_idx ON user_interests (interest_code, user_id);

-- ------------------------------------------------------------- generations --

CREATE TABLE pixel_generations (
    id                   UUID PRIMARY KEY,
    user_id              UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status               VARCHAR(24)  NOT NULL DEFAULT 'QUEUED',
    style                VARCHAR(32)  NOT NULL DEFAULT 'PIXME_BASIC',
    provider             VARCHAR(32)  NOT NULL,
    model                VARCHAR(64),
    prompt_version       VARCHAR(32)  NOT NULL,
    -- Storage keys, not URLs: the bucket/CDN host is configuration.
    original_object_key  VARCHAR(512) NOT NULL,
    generated_object_key VARCHAR(512),
    -- Structured description of what the model saw (hair, top, bottom, …).
    -- Kept so prompts can be re-run and compared across prompt versions.
    analysis_json        TEXT,
    progress             SMALLINT     NOT NULL DEFAULT 0,
    failure_reason       VARCHAR(32),
    error_message        VARCHAR(512),
    used_free_generation BOOLEAN      NOT NULL DEFAULT FALSE,
    used_credit          BOOLEAN      NOT NULL DEFAULT FALSE,
    -- Set when a consumed credit has been returned, so a retry of the refund
    -- path can never double-credit.
    credit_refunded_at   TIMESTAMPTZ,
    post_date            DATE         NOT NULL,
    attempt              SMALLINT     NOT NULL DEFAULT 1,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    started_at           TIMESTAMPTZ,
    completed_at         TIMESTAMPTZ,
    CONSTRAINT pixel_generations_status_check
        CHECK (status IN ('QUEUED', 'PROCESSING', 'COMPLETED', 'FAILED', 'REJECTED_UNSAFE')),
    CONSTRAINT pixel_generations_progress_check
        CHECK (progress BETWEEN 0 AND 100),
    CONSTRAINT pixel_generations_failure_check
        CHECK (failure_reason IS NULL OR failure_reason IN
            ('UNSAFE_IMAGE', 'NO_PERSON_DETECTED', 'PROVIDER_ERROR', 'TIMEOUT', 'INTERNAL'))
);

CREATE INDEX pixel_generations_user_date_idx
    ON pixel_generations (user_id, post_date DESC, created_at DESC);
CREATE INDEX pixel_generations_status_idx
    ON pixel_generations (status, created_at)
    WHERE status IN ('QUEUED', 'PROCESSING');

-- Uploaded originals waiting to be turned into a character. Separate from
-- generations so an abandoned upload is trivially reapable.
CREATE TABLE pixel_uploads (
    id          UUID PRIMARY KEY,
    user_id     UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    object_key  VARCHAR(512) NOT NULL,
    mime_type   VARCHAR(64)  NOT NULL,
    byte_size   BIGINT       NOT NULL DEFAULT 0,
    consumed_at TIMESTAMPTZ,
    expires_at  TIMESTAMPTZ  NOT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX pixel_uploads_user_idx ON pixel_uploads (user_id, created_at DESC);
CREATE INDEX pixel_uploads_reap_idx ON pixel_uploads (expires_at) WHERE consumed_at IS NULL;

-- -------------------------------------------------------------- pixel posts --

CREATE TABLE pixel_posts (
    id                   UUID PRIMARY KEY,
    user_id              UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    generation_id        UUID         NOT NULL REFERENCES pixel_generations (id),
    character_object_key VARCHAR(512) NOT NULL,
    -- Nullable: cleared when the user deletes the original or opted out of
    -- retention. The character and the record survive either way.
    original_object_key  VARCHAR(512),
    caption              VARCHAR(60),
    mood                 VARCHAR(16),
    style                VARCHAR(32)  NOT NULL DEFAULT 'PIXME_BASIC',
    visibility           VARCHAR(16)  NOT NULL DEFAULT 'PUBLIC',
    heart_count          INTEGER      NOT NULL DEFAULT 0,
    -- Impressions, used by ranking to compute a reaction *rate* rather than a
    -- raw count — this is what stops popular users monopolising the rails.
    view_count           INTEGER      NOT NULL DEFAULT 0,
    post_date            DATE         NOT NULL,
    is_representative    BOOLEAN      NOT NULL DEFAULT FALSE,
    published_at         TIMESTAMPTZ,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    deleted_at           TIMESTAMPTZ,
    CONSTRAINT pixel_posts_visibility_check
        CHECK (visibility IN ('PUBLIC', 'PRIVATE')),
    CONSTRAINT pixel_posts_heart_count_check CHECK (heart_count >= 0)
);

-- The core product rule, enforced by the database rather than by application
-- discipline: at most ONE representative PIXME per user per calendar day.
CREATE UNIQUE INDEX pixel_posts_one_representative_per_day
    ON pixel_posts (user_id, post_date)
    WHERE is_representative AND deleted_at IS NULL;

CREATE INDEX pixel_posts_today_feed_idx
    ON pixel_posts (post_date DESC, published_at DESC)
    WHERE is_representative AND visibility = 'PUBLIC' AND deleted_at IS NULL;
CREATE INDEX pixel_posts_user_history_idx
    ON pixel_posts (user_id, post_date DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX pixel_posts_generation_idx ON pixel_posts (generation_id);

CREATE TABLE pixel_post_tags (
    post_id UUID        NOT NULL REFERENCES pixel_posts (id) ON DELETE CASCADE,
    tag     VARCHAR(12) NOT NULL,
    PRIMARY KEY (post_id, tag)
);

CREATE INDEX pixel_post_tags_tag_idx ON pixel_post_tags (tag, post_id);

-- --------------------------------------------------------------- reactions --

CREATE TABLE reactions (
    id           UUID PRIMARY KEY,
    from_user_id UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    post_id      UUID        NOT NULL REFERENCES pixel_posts (id) ON DELETE CASCADE,
    type         VARCHAR(16) NOT NULL DEFAULT 'HEART',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT reactions_type_check CHECK (type IN ('HEART'))
);

-- Makes "no double hearts" a database guarantee, which is what lets the API
-- be safely idempotent under a double-tap.
CREATE UNIQUE INDEX reactions_unique_per_user_post_type
    ON reactions (from_user_id, post_id, type);
CREATE INDEX reactions_post_idx ON reactions (post_id, created_at DESC);
CREATE INDEX reactions_from_user_idx ON reactions (from_user_id, created_at DESC);

-- -------------------------------------------------------------- connections --

CREATE TABLE connection_requests (
    id           UUID PRIMARY KEY,
    from_user_id UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    to_user_id   UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status       VARCHAR(16) NOT NULL DEFAULT 'REQUESTED',
    -- The post that prompted the wave, for "오늘의 PIXME를 계기로" context.
    source_post_id UUID,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT connection_requests_status_check
        CHECK (status IN ('REQUESTED', 'CONNECTED', 'CANCELLED', 'BLOCKED')),
    CONSTRAINT connection_requests_not_self CHECK (from_user_id <> to_user_id)
);

CREATE UNIQUE INDEX connection_requests_unique_pair
    ON connection_requests (from_user_id, to_user_id);
CREATE INDEX connection_requests_incoming_idx
    ON connection_requests (to_user_id, status, created_at DESC);

CREATE TABLE connections (
    id            UUID PRIMARY KEY,
    -- Stored ordered (user_a < user_b) so a pair has exactly one row and the
    -- unique index below cannot be bypassed by argument order.
    user_a_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    user_b_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    connected_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    a_acknowledged BOOLEAN    NOT NULL DEFAULT FALSE,
    b_acknowledged BOOLEAN    NOT NULL DEFAULT FALSE,
    ended_at      TIMESTAMPTZ,
    CONSTRAINT connections_ordered CHECK (user_a_id < user_b_id)
);

CREATE UNIQUE INDEX connections_unique_pair ON connections (user_a_id, user_b_id);
CREATE INDEX connections_user_a_idx ON connections (user_a_id, connected_at DESC);
CREATE INDEX connections_user_b_idx ON connections (user_b_id, connected_at DESC);

-- --------------------------------------------------------------------- chat --

CREATE TABLE conversations (
    id              UUID PRIMARY KEY,
    connection_id   UUID        NOT NULL REFERENCES connections (id) ON DELETE CASCADE,
    last_message_at TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX conversations_connection_key ON conversations (connection_id);

CREATE TABLE conversation_members (
    conversation_id      UUID        NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
    user_id              UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    last_read_message_id UUID,
    last_read_at         TIMESTAMPTZ,
    unread_count         INTEGER     NOT NULL DEFAULT 0,
    muted                BOOLEAN     NOT NULL DEFAULT FALSE,
    left_at              TIMESTAMPTZ,
    PRIMARY KEY (conversation_id, user_id),
    CONSTRAINT conversation_members_unread_check CHECK (unread_count >= 0)
);

CREATE INDEX conversation_members_user_idx ON conversation_members (user_id);

CREATE TABLE messages (
    id                UUID PRIMARY KEY,
    conversation_id   UUID         NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
    -- NULL for SYSTEM messages (e.g. the "마음이 통했어요" opener).
    sender_id         UUID         REFERENCES users (id) ON DELETE SET NULL,
    type              VARCHAR(16)  NOT NULL DEFAULT 'TEXT',
    content           VARCHAR(2000) NOT NULL,
    -- Client-generated; makes send idempotent across the socket/REST fallback.
    client_message_id VARCHAR(64),
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    read_at           TIMESTAMPTZ,
    deleted_at        TIMESTAMPTZ,
    CONSTRAINT messages_type_check CHECK (type IN ('TEXT', 'SYSTEM'))
);

CREATE INDEX messages_conversation_idx
    ON messages (conversation_id, created_at DESC, id DESC);
CREATE UNIQUE INDEX messages_client_id_key
    ON messages (conversation_id, client_message_id)
    WHERE client_message_id IS NOT NULL;

-- ------------------------------------------------------------ notifications --

CREATE TABLE notifications (
    id         UUID PRIMARY KEY,
    user_id    UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    type       VARCHAR(32)  NOT NULL,
    title      VARCHAR(120) NOT NULL,
    body       VARCHAR(255) NOT NULL,
    -- Actor's character thumbnail, when there is an actor.
    image_object_key VARCHAR(512),
    deep_link  VARCHAR(255),
    -- Used to collapse repeated events ("3명이 하트를 보냈어요") instead of
    -- sending one notification per heart.
    group_key  VARCHAR(120),
    read_at    TIMESTAMPTZ,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT notifications_type_check CHECK (type IN
        ('HEART', 'CONNECTION_REQUEST', 'CONNECTED', 'MESSAGE', 'REACTION_SPIKE',
         'DAILY_REMINDER', 'GENERATION_COMPLETED', 'SYSTEM'))
);

CREATE INDEX notifications_user_idx ON notifications (user_id, created_at DESC);
CREATE INDEX notifications_unread_idx
    ON notifications (user_id) WHERE read_at IS NULL;
CREATE UNIQUE INDEX notifications_group_key
    ON notifications (user_id, group_key) WHERE group_key IS NOT NULL;

CREATE TABLE push_tokens (
    token       VARCHAR(255) PRIMARY KEY,
    user_id     UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    platform    VARCHAR(16)  NOT NULL,
    app_version VARCHAR(24),
    -- Cleared when the push service reports the token as dead.
    invalid_at  TIMESTAMPTZ,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT push_tokens_platform_check CHECK (platform IN ('IOS', 'ANDROID'))
);

CREATE INDEX push_tokens_user_idx ON push_tokens (user_id) WHERE invalid_at IS NULL;

-- ------------------------------------------------------------ monetization --

CREATE TABLE products (
    code              VARCHAR(48) PRIMARY KEY,
    kind              VARCHAR(24)  NOT NULL,
    ios_product_id    VARCHAR(128),
    android_product_id VARCHAR(128),
    name              VARCHAR(64)  NOT NULL,
    description       VARCHAR(255) NOT NULL,
    -- Display fallback only; the store's localised price always wins in the UI.
    fallback_price_krw INTEGER     NOT NULL DEFAULT 0,
    credit_amount     INTEGER,
    unlock_code       VARCHAR(48),
    badge             VARCHAR(24),
    sort_order        INTEGER      NOT NULL DEFAULT 0,
    active            BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT products_kind_check
        CHECK (kind IN ('CREDIT_PACK', 'STYLE', 'DECORATION', 'SUBSCRIPTION'))
);

CREATE TABLE purchases (
    id                UUID PRIMARY KEY,
    user_id           UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    product_code      VARCHAR(48)  NOT NULL REFERENCES products (code),
    platform          VARCHAR(16)  NOT NULL,
    store_product_id  VARCHAR(128) NOT NULL,
    -- Store transaction id. Unique so a replayed receipt cannot grant twice.
    transaction_id    VARCHAR(191) NOT NULL,
    original_transaction_id VARCHAR(191),
    status            VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    granted_at        TIMESTAMPTZ,
    revoked_at        TIMESTAMPTZ,
    raw_receipt       TEXT,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT purchases_platform_check CHECK (platform IN ('IOS', 'ANDROID')),
    CONSTRAINT purchases_status_check
        CHECK (status IN ('PENDING', 'GRANTED', 'REVOKED', 'INVALID'))
);

CREATE UNIQUE INDEX purchases_transaction_key ON purchases (platform, transaction_id);
CREATE INDEX purchases_user_idx ON purchases (user_id, created_at DESC);

CREATE TABLE subscriptions (
    id                      UUID PRIMARY KEY,
    user_id                 UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    product_code            VARCHAR(48)  NOT NULL REFERENCES products (code),
    platform                VARCHAR(16)  NOT NULL,
    original_transaction_id VARCHAR(191) NOT NULL,
    status                  VARCHAR(24)  NOT NULL,
    current_period_end      TIMESTAMPTZ  NOT NULL,
    auto_renewing           BOOLEAN      NOT NULL DEFAULT TRUE,
    -- Monthly credit grant bookkeeping, so a renewal grants exactly once.
    last_grant_period_end   TIMESTAMPTZ,
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT subscriptions_platform_check CHECK (platform IN ('IOS', 'ANDROID')),
    CONSTRAINT subscriptions_status_check
        CHECK (status IN ('ACTIVE', 'GRACE_PERIOD', 'EXPIRED', 'CANCELLED', 'BILLING_RETRY'))
);

CREATE UNIQUE INDEX subscriptions_original_transaction_key
    ON subscriptions (platform, original_transaction_id);
CREATE INDEX subscriptions_user_active_idx
    ON subscriptions (user_id, status, current_period_end DESC);

-- Paid credits are tracked separately from the daily free generation so the
-- two can never be confused by the generation path.
CREATE TABLE generation_credits (
    user_id                   UUID PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    credit_count              INTEGER NOT NULL DEFAULT 0,
    last_free_generation_date DATE,
    free_used_today           SMALLINT NOT NULL DEFAULT 0,
    updated_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT generation_credits_non_negative CHECK (credit_count >= 0)
);

CREATE TABLE credit_ledger (
    id            UUID PRIMARY KEY,
    user_id       UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    delta         INTEGER     NOT NULL,
    reason        VARCHAR(32) NOT NULL,
    balance_after INTEGER     NOT NULL,
    -- Generation or purchase this entry belongs to.
    reference_id  UUID,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT credit_ledger_reason_check CHECK (reason IN
        ('PURCHASE', 'GENERATION', 'GENERATION_REFUND', 'SUBSCRIPTION_GRANT',
         'PROMOTION', 'REWARD_AD'))
);

CREATE INDEX credit_ledger_user_idx ON credit_ledger (user_id, created_at DESC);
-- A refund for a given generation may exist at most once.
CREATE UNIQUE INDEX credit_ledger_refund_key
    ON credit_ledger (reference_id, reason)
    WHERE reason = 'GENERATION_REFUND';

CREATE TABLE user_unlocks (
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    unlock_code VARCHAR(48) NOT NULL,
    kind        VARCHAR(24) NOT NULL,
    source      VARCHAR(24) NOT NULL DEFAULT 'PURCHASE',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, unlock_code),
    CONSTRAINT user_unlocks_kind_check CHECK (kind IN ('STYLE', 'DECORATION'))
);

-- ------------------------------------------------------------------ safety --

CREATE TABLE blocks (
    blocker_id UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    blocked_id UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (blocker_id, blocked_id),
    CONSTRAINT blocks_not_self CHECK (blocker_id <> blocked_id)
);

-- Blocking is symmetric in effect, so filtering needs both directions indexed.
CREATE INDEX blocks_blocked_idx ON blocks (blocked_id, blocker_id);

CREATE TABLE reports (
    id           UUID PRIMARY KEY,
    reporter_id  UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    target_type  VARCHAR(24)  NOT NULL,
    target_id    UUID         NOT NULL,
    -- Denormalised so moderation can act on the account even if the post is
    -- deleted before review.
    target_user_id UUID       REFERENCES users (id) ON DELETE SET NULL,
    reason       VARCHAR(32)  NOT NULL,
    detail       VARCHAR(500),
    status       VARCHAR(24)  NOT NULL DEFAULT 'OPEN',
    resolution   VARCHAR(32),
    resolved_at  TIMESTAMPTZ,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT reports_target_type_check
        CHECK (target_type IN ('USER', 'PIXEL_POST', 'MESSAGE')),
    CONSTRAINT reports_reason_check CHECK (reason IN
        ('INAPPROPRIATE_CONTENT', 'HARASSMENT', 'IMPERSONATION', 'SPAM',
         'SEXUAL_CONTENT', 'HATE_SPEECH', 'OTHER')),
    CONSTRAINT reports_status_check
        CHECK (status IN ('OPEN', 'REVIEWING', 'ACTIONED', 'DISMISSED'))
);

CREATE INDEX reports_status_idx ON reports (status, created_at);
CREATE INDEX reports_target_idx ON reports (target_type, target_id);
CREATE INDEX reports_reporter_idx ON reports (reporter_id, created_at DESC);

-- -------------------------------------------------------------------- auth --

CREATE TABLE refresh_tokens (
    id           UUID PRIMARY KEY,
    user_id      UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- SHA-256 of the token. The raw value is never stored.
    token_hash   VARCHAR(64)  NOT NULL,
    expires_at   TIMESTAMPTZ  NOT NULL,
    revoked_at   TIMESTAMPTZ,
    -- Set when this token was exchanged, enabling reuse detection.
    rotated_to   UUID,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX refresh_tokens_hash_key ON refresh_tokens (token_hash);
CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id, expires_at DESC);

-- -------------------------------------------------------- feed / discovery --

-- Per-viewer exposure log. Lets ranking cap how often one author can appear in
-- a single person's day, which is the main lever against the feed feeling like
-- the same ten faces.
CREATE TABLE feed_exposures (
    viewer_id  UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    post_id    UUID        NOT NULL REFERENCES pixel_posts (id) ON DELETE CASCADE,
    author_id  UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    post_date  DATE        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (viewer_id, post_id)
);

CREATE INDEX feed_exposures_author_day_idx
    ON feed_exposures (viewer_id, author_id, post_date);
CREATE INDEX feed_exposures_day_idx ON feed_exposures (post_date);

-- ------------------------------------------------------------------ square --

CREATE TABLE square_scenes (
    code        VARCHAR(32) PRIMARY KEY,
    name        VARCHAR(48) NOT NULL,
    version     INTEGER     NOT NULL DEFAULT 1,
    sky_color   VARCHAR(16) NOT NULL,
    ground_color VARCHAR(16) NOT NULL,
    accent_color VARCHAR(16) NOT NULL,
    -- JSON array of {code,x,y,scale,zIndex}. Props are data so the square can
    -- be re-dressed per season without a deploy.
    props_json  TEXT        NOT NULL,
    -- Selection rules: hour range and month range this scene applies to.
    from_hour   SMALLINT    NOT NULL DEFAULT 0,
    to_hour     SMALLINT    NOT NULL DEFAULT 24,
    from_month  SMALLINT    NOT NULL DEFAULT 1,
    to_month    SMALLINT    NOT NULL DEFAULT 12,
    priority    INTEGER     NOT NULL DEFAULT 0,
    active      BOOLEAN     NOT NULL DEFAULT TRUE
);

-- Placement is computed once per (day, post) and then stable, so the square
-- doesn't rearrange itself every time someone pulls to refresh.
CREATE TABLE square_placements (
    post_date    DATE        NOT NULL,
    post_id      UUID        NOT NULL REFERENCES pixel_posts (id) ON DELETE CASCADE,
    user_id      UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    x            INTEGER     NOT NULL,
    y            INTEGER     NOT NULL,
    depth        SMALLINT    NOT NULL DEFAULT 0,
    idle_variant SMALLINT    NOT NULL DEFAULT 0,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (post_date, post_id)
);

CREATE INDEX square_placements_day_idx ON square_placements (post_date, y);
CREATE UNIQUE INDEX square_placements_user_day_key
    ON square_placements (post_date, user_id);
